import{_ as p,o as s,c as n,a2 as e}from"./chunks/framework.BZAK_utg.js";const m=JSON.parse('{"title":"ArchLinux下LAMP的安装","description":"","frontmatter":{"title":"ArchLinux下LAMP的安装","date":"2019-12-11","categories":["安装配置","应用软件"],"tags":["Linux"],"prevTitle":"Java文件流与策略模式的综合运用：用两种方式完成文件读写操作","prevLink":"../编程语言/Java文件流与策略模式的综合运用：用两种方式完成文件读写操作.html","nextTitle":"ArchLinux系统安装与配置","nextLink":"./ArchLinux系统安装与配置.html"},"headers":[],"relativePath":"posts/安装配置/ArchLinux下LAMP的安装.md","filePath":"posts/安装配置/ArchLinux下LAMP的安装.md"}'),l={name:"posts/安装配置/ArchLinux下LAMP的安装.md"};function t(i,a,o,c,d,r){return s(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="archlinux下lamp的安装" tabindex="-1">ArchLinux下LAMP的安装 <a class="header-anchor" href="#archlinux下lamp的安装" aria-label="Permalink to &quot;ArchLinux下LAMP的安装&quot;">​</a></h1><h3 id="_1-apache与php" tabindex="-1"><strong>1. apache与php</strong> <a class="header-anchor" href="#_1-apache与php" aria-label="Permalink to &quot;**1. apache与php**&quot;">​</a></h3><p><code>pacman -S php-apache</code> （安装apache、php、php扩展:libphp）</p><p><code>mousepad /etc/httpd/conf/httpd.conf</code> （配置apache——php扩展）</p><blockquote><p>参见<a href="https://wiki.archlinux.org/index.php/Apache_HTTP_Server#PHP" target="_blank" rel="noreferrer">Archlinux wiki</a></p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>------------------------------</span></span>
<span class="line"><span>#LoadModule mpm_event_module modules/mod_mpm_event.so（注释）</span></span>
<span class="line"><span>LoadModule mpm_prefork_module modules/mod_mpm_prefork.so</span></span>
<span class="line"><span>（去掉注释）</span></span>
<span class="line"><span>.</span></span>
<span class="line"><span>LoadModule php7_module modules/libphp7.so</span></span>
<span class="line"><span>AddHandler php7-script php （将这一行放在LoadModule 的末尾）</span></span>
<span class="line"><span>.</span></span>
<span class="line"><span>Include conf/extra/php7_module.conf （将这一行放到Include列表的末尾）</span></span>
<span class="line"><span>------------------------------</span></span></code></pre></div><blockquote><p>使用命令：“php -S localhost:8000 -t public_html/ ”可以独立运行PHP</p></blockquote><h3 id="_2-mysql" tabindex="-1"><strong>2. mysql</strong> <a class="header-anchor" href="#_2-mysql" aria-label="Permalink to &quot;**2. mysql**&quot;">​</a></h3><p><code>pacman -S mariadb</code> （安装mysql数据库）</p><p><code>mysql_install_db --user=mysql --basedir=/usr --datadir=/var/lib/mysql</code> （mysql目录配置）</p><p><code>systemctl start mysqld</code> （启动数据库）</p><p><code>mysql_secure_installation</code> （mysql安全配置）</p><p><code>pacman -S dbeaver</code> （安装数据库管理工具）</p><h3 id="_3-phpmyadmin" tabindex="-1"><strong>3. phpmyadmin</strong> <a class="header-anchor" href="#_3-phpmyadmin" aria-label="Permalink to &quot;**3. phpmyadmin**&quot;">​</a></h3><p><code>pacman -S phpmyadmin</code> （安装phpmyadmin）</p><p><code>mousepad /etc/httpd/conf/extra/phpmyadmin.conf</code> （创建Apache配置文件）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>------------------------------</span></span>
<span class="line"><span>Alias /phpmyadmin &quot;/usr/share/webapps/phpMyAdmin&quot;</span></span>
<span class="line"><span>&lt;Directory &quot;/usr/share/webapps/phpMyAdmin&quot;&gt;</span></span>
<span class="line"><span>  DirectoryIndex index.php</span></span>
<span class="line"><span>  AllowOverride All</span></span>
<span class="line"><span>  Options FollowSymlinks</span></span>
<span class="line"><span>  Require all granted</span></span>
<span class="line"><span>&lt;/Directory&gt;</span></span>
<span class="line"><span>------------------------------</span></span></code></pre></div><p><code>mousepad /etc/httpd/conf/httpd.conf</code> （将上个文件的引用加入到httpd.conf）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>------------------------------</span></span>
<span class="line"><span># phpMyAdmin configuration</span></span>
<span class="line"><span>Include conf/extra/phpmyadmin.conf （将这一行放到Include列表的末尾）</span></span>
<span class="line"><span>------------------------------</span></span></code></pre></div><p>//<code>mousepad /etc/webapps/phpmyadmin/config.inc.php</code> （配置phpmyadmin）</p><p><code>mousepad /etc/php/php.ini</code> （配置mysqli 扩展）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>------------------------------</span></span>
<span class="line"><span>extension=mysqli（去掉;注释）</span></span>
<span class="line"><span>------------------------------</span></span></code></pre></div><blockquote><p>不执行上述操作的话，在进入phpmyadmin时会显示&quot;缺少 mysqli 扩展“</p></blockquote><p>LNMP安装可参见<a href="https://www.linuxdashen.com/install-lemp-nginx-mariadb-php7-arch-linux-server" target="_blank" rel="noreferrer">Arch Linux服务器安装LNMP (Nginx, MariaDB, PHP7)</a></p>`,24)])])}const u=p(l,[["render",t]]);export{m as __pageData,u as default};
